/** Test-only native controller. Client C2S actions perform table/anvil/combat operations. */
public final class Stage21FNetworkServer implements ModInitializer {
 private Path dir;private int phase,ticks,index,combat,start;private long nonce=System.currentTimeMillis();private long[] sent=new long[2];private final String[] names={"WBOne","WBTwo"};private final Map<String,Object> results=new LinkedHashMap<>();
 private final List<RegistryKey<Enchantment>> keys=List.of(SwordEnchantments.BANE,SwordEnchantments.FROST,SwordEnchantments.BLOOD,SwordEnchantments.RUNIC);
 private final LivingEntity[] targets=new LivingEntity[2],nearby=new LivingEntity[2];private final boolean[] frosted=new boolean[2];private final List<String> combatItems=List.of("minecraft:diamond_sword","simplyswords:iron_longsword","simplyswords:iron_claymore","simplyswords:emberblade","simplyswords:iron_longsword");
 private void check(boolean ok,String message){if(!ok)throw new IllegalStateException(message);}
 private void write(String name,Object data)throws Exception{var p=dir.resolve(name);var t=p.resolveSibling(name+".tmp");Files.writeString(t,new GsonBuilder().setPrettyPrinting().create().toJson(data));Files.move(t,p,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}
 private JsonObject read(String name)throws Exception{return JsonParser.parseString(Files.readString(dir.resolve(name))).getAsJsonObject();}
 private void command(int i,String action,Object...args)throws Exception{var j=new JsonObject();j.addProperty("nonce",++nonce);sent[i]=nonce;j.addProperty("action",action);for(int n=0;n<args.length;n+=2)j.addProperty(args[n].toString(),args[n+1].toString());write(names[i]+".command.json",j);}
 private void both(String action,Object...args)throws Exception{for(int i=0;i<2;i++)command(i,action,args);}
 private boolean ack(int i)throws Exception{return Files.exists(dir.resolve(names[i]+".reply.json"))&&read(names[i]+".reply.json").get("nonce").getAsLong()==sent[i];}
 private RegistryEntry<Enchantment> entry(ServerWorld w,RegistryKey<Enchantment> key){return w.getRegistryManager().get(RegistryKeys.ENCHANTMENT).entryOf(key);}
 private ItemStack found(ServerPlayerEntity p,RegistryKey<Enchantment> key,boolean book){for(int i=0;i<p.getInventory().size();i++){var s=p.getInventory().getStack(i);if(s.isOf(Items.ENCHANTED_BOOK)==book&&EnchantmentHelper.getEnchantments(s).getLevel(entry(p.getServerWorld(),key))>0)return s;}return ItemStack.EMPTY;}
 private LivingEntity mob(ServerWorld w,int lane,double offset){var e=com.witchersbestiary.entity.ModEntities.GHOUL.create(w);e.refreshPositionAndAngles(lane*24,129,offset,180,0);e.setAiDisabled(true);e.setPersistent();e.setNoGravity(true);e.noClip=true;e.getAttributeInstance(EntityAttributes.GENERIC_MAX_HEALTH).setBaseValue(500);e.getAttributeInstance(EntityAttributes.GENERIC_ARMOR).setBaseValue(0);e.setHealth(500);w.spawnEntity(e);return e;}
 private void prepareTable(ServerPlayerEntity p,int lane)throws Exception{p.closeHandledScreen();p.getInventory().clear();p.addExperienceLevels(40-p.experienceLevel);var w=p.getServerWorld();var pos=new BlockPos(lane*24,129,0);p.teleport(w,pos.getX()+.5,129,-.7,0,0);int expected=w.getRegistryManager().get(RegistryKeys.ENCHANTMENT).getRawId(entry(w,keys.get(index)).value());EnchantmentScreenHandler chosen=null;for(int seed=0;seed<10000;seed++){p.getRandom().setSeed(seed+index*10000L);p.applyEnchantmentCosts(ItemStack.EMPTY,0);var h=new EnchantmentScreenHandler(p.currentScreenHandler.syncId+1,p.getInventory(),ScreenHandlerContext.create(w,pos));h.getSlot(0).setStack(new ItemStack(Items.BOOK));h.getSlot(1).setStack(new ItemStack(Items.LAPIS_LAZULI,64));h.onContentChanged(h.getSlot(0).inventory);if(h.enchantmentId[2]==expected){chosen=h;break;}}check(chosen!=null,"Table seed for ordinary book "+keys.get(index));final var h=chosen;p.openHandledScreen(new net.minecraft.screen.SimpleNamedScreenHandlerFactory((id,inv,owner)->{var live=new EnchantmentScreenHandler(id,inv,ScreenHandlerContext.create(w,pos));live.getSlot(0).setStack(new ItemStack(Items.BOOK));live.getSlot(1).setStack(new ItemStack(Items.LAPIS_LAZULI,64));live.onContentChanged(live.getSlot(0).inventory);return live;},net.minecraft.text.Text.literal("Stage21F Survival enchanting")));check(((EnchantmentScreenHandler)p.currentScreenHandler).enchantmentId[2]==expected,"Live seeded table offer");results.put("table_offer_"+index+"_"+lane,Map.of("seed",h.getSeed(),"cost",h.enchantmentPower[2],"level",h.enchantmentLevel[2]));}
 public void onInitialize(){if(!Boolean.getBoolean("witchersbestiary.stage21fNetwork"))return;dir=Path.of(System.getProperty("witchersbestiary.stage20eOutput"));phase=Files.exists(dir.resolve("enchantment-resume.json"))?100:0;ServerTickEvents.END_SERVER_TICK.register(s->{try{if(phase==999)return;if(++ticks>12000)throw new IllegalStateException("Native enchantment timeout phase="+phase);if(phase==90){if(!ack(0)||!ack(1))return;both("wait");s.getPlayerManager().saveAllPlayerData();s.save(false,true,true);phase=999;s.stop(false);return;}var a=s.getPlayerManager().getPlayer(names[0]);var b=s.getPlayerManager().getPlayer(names[1]);if(a==null||b==null)return;var players=List.of(a,b);var w=s.getOverworld();if(ticks%100==0)write("enchantment-heartbeat.json",Map.of("phase",phase,"ticks",ticks,"combat",combat,"table",index));switch(phase){
 case 0->{w.getGameRules().get(net.minecraft.world.GameRules.DO_MOB_SPAWNING).set(false,s);for(int lane=0;lane<2;lane++){for(int x=-7;x<=7;x++)for(int z=-7;z<=7;z++){w.setBlockState(new BlockPos(lane*24+x,128,z),Blocks.STONE.getDefaultState());for(int y=129;y<136;y++)w.setBlockState(new BlockPos(lane*24+x,y,z),Blocks.AIR.getDefaultState());}var table=new BlockPos(lane*24,129,0);w.setBlockState(table,Blocks.ENCHANTING_TABLE.getDefaultState());w.setBlockState(table.add(4,0,0),Blocks.ANVIL.getDefaultState());for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++)if(Math.abs(x)==2||Math.abs(z)==2)w.setBlockState(table.add(x,0,z),Blocks.BOOKSHELF.getDefaultState());var p=players.get(lane);p.changeGameMode(net.minecraft.world.GameMode.SURVIVAL);p.setInvulnerable(false);p.getHungerManager().setFoodLevel(10);}results.put("betterCombat",net.fabricmc.loader.api.FabricLoader.getInstance().isModLoaded("bettercombat"));results.put("simplySwords",net.fabricmc.loader.api.FabricLoader.getInstance().isModLoaded("simplyswords"));both("wait");phase=1;}
 case 1->{if(!ack(0)||!ack(1))return;for(int i=0;i<2;i++)prepareTable(players.get(i),i);both("enchTable","name",keys.get(index).getValue());phase=2;}
 case 2->{if(!ack(0)||!ack(1))return;for(int i=0;i<2;i++){var p=players.get(i);var book=found(p,keys.get(index),true).copy();check(!book.isEmpty()&&p.experienceLevel==37&&((EnchantmentScreenHandler)p.currentScreenHandler).getLapisCount()==61,"Real table consumed three XP levels/lapis and enchanted book");p.closeHandledScreen();p.getInventory().clear();var pos=new BlockPos(i*24+4,129,0);w.setBlockState(pos,Blocks.ANVIL.getDefaultState());p.teleport(w,pos.getX(),129,-2,0,0);p.openHandledScreen(new SimpleNamedScreenHandlerFactory((id,inv,owner)->new AnvilScreenHandler(id,inv,ScreenHandlerContext.create(w,pos)),net.minecraft.text.Text.literal("Stage21F Survival anvil")));p.currentScreenHandler.getSlot(0).setStack(new ItemStack(Items.IRON_SWORD));p.currentScreenHandler.getSlot(1).setStack(book);((AnvilScreenHandler)p.currentScreenHandler).updateResult();check(!p.currentScreenHandler.getSlot(2).getStack().isEmpty(),"Ordinary Survival anvil result");p.currentScreenHandler.sendContentUpdates();}both("enchAnvil","name",keys.get(index).getValue());phase=3;}
 case 3->{if(!ack(0)||!ack(1))return;for(var p:players){check(!found(p,keys.get(index),false).isEmpty()&&p.experienceLevel<37,"Real native anvil output taken and XP charged");p.closeHandledScreen();}results.put("survival_table_book_anvil_"+keys.get(index).getValue(),true);if(++index<4){both("wait");phase=1;}else{both("wait");phase=10;}}
 case 10->{if(!ack(0)||!ack(1))return;if(combat==0){for(int lane=0;lane<2;lane++)for(int x=-7;x<=7;x++)for(int z=-7;z<=7;z++)for(int y=129;y<136;y++)w.setBlockState(new BlockPos(lane*24+x,y,z),Blocks.AIR.getDefaultState());}if(combat>=combatItems.size()){phase=40;break;}var id=net.minecraft.util.Identifier.of(combatItems.get(combat));if(!Registries.ITEM.containsId(id)){results.put("unavailable_"+id,true);combat++;break;}for(int i=0;i<2;i++){var p=players.get(i);p.closeHandledScreen();p.getInventory().clear();p.getInventory().selectedSlot=0;var weapon=new ItemStack(Registries.ITEM.get(id));check(SwordEnchantments.sword(weapon),"Native eligible sword "+id);for(var key:keys)check(entry(w,key).value().isSupportedItem(weapon)&&entry(w,key).value().isPrimaryItem(weapon),"Native table/anvil sword eligibility "+id);for(var key:keys)if(combat!=4||key==SwordEnchantments.BANE||key==SwordEnchantments.FROST)weapon.addEnchantment(entry(w,key),3);p.getInventory().setStack(0,weapon);if(combat==4){var off=new ItemStack(Registries.ITEM.get(id));off.addEnchantment(entry(w,SwordEnchantments.RUNIC),3);off.addEnchantment(entry(w,SwordEnchantments.BLOOD),3);p.getInventory().offHand.set(0,off);}p.setHealth(10);((SwordEnchantmentState)p).bestiary$harvestReady(0);((SwordEnchantmentState)p).bestiary$pulseReady(0);p.teleport(w,i*24,129,2.4,180,0);targets[i]=mob(w,i,0);nearby[i]=mob(w,i,1.6);frosted[i]=false;command(i,"enchAttack","target",targets[i].getId(),"ticks",combat==4?420:180,"name",id);}start=ticks;phase=11;}
 case 11->{for(int i=0;i<2;i++)frosted[i]|=targets[i].hasStatusEffect(StatusEffects.SLOWNESS);if(!ack(0)||!ack(1))return;for(int i=0;i<2;i++){var p=players.get(i);check(targets[i].getHealth()<500,"Actual native BC damage "+combatItems.get(combat));check(frosted[i]&&p.getHealth()>10,"Native frost and healing "+combatItems.get(combat));check(nearby[i].getHealth()<500,"Native runic or BC multi-target damage "+combatItems.get(combat));check(((SwordEnchantmentState)p).bestiary$pulseReady()>0,"Native threshold produced a real runic pulse "+combatItems.get(combat)+" main="+p.getMainHandStack().get(SwordEnchantments.RUNIC_STATE)+" off="+p.getOffHandStack().get(SwordEnchantments.RUNIC_STATE));if(combat==4)check(!p.getMainHandStack().contains(SwordEnchantments.RUNIC_STATE)&&p.getOffHandStack().contains(SwordEnchantments.RUNIC_STATE),"BC actual offhand owns charge; main hand cannot inherit it");results.put("native_combat_"+combat+"_"+combatItems.get(combat)+"_"+i,Map.of("targetHP",targets[i].getHealth(),"nearbyHP",nearby[i].getHealth(),"playerHP",p.getHealth(),"rune",p.getMainHandStack().getOrDefault(SwordEnchantments.RUNIC_STATE,RunicState.EMPTY).toString()));targets[i].discard();nearby[i].discard();}combat++;both("wait");phase=10;}
 case 40->{var saved=new LinkedHashMap<String,Object>();for(int i=0;i<2;i++){var p=players.get(i);p.closeHandledScreen();check(p.getMainHandStack().contains(SwordEnchantments.RUNIC_STATE)||p.getOffHandStack().contains(SwordEnchantments.RUNIC_STATE),"Only naturally earned native charge/cooldown snapshots may be persisted");saved.put(names[i],p.getInventory().writeNbt(new NbtList()).toString());saved.put(names[i]+"Cooldown",((SwordEnchantmentState)p).bestiary$harvestReady());}results.put("restart_fixture","Exact weapons and cooldowns from the preceding actual native combat; no state is injected");write("enchantment-results.json",results);write("enchantment-resume.json",saved);write("resume.json",Map.of("stage21f",true));both("disconnect");phase=90;}
 case 100->{var saved=read("enchantment-resume.json");for(int i=0;i<2;i++){var p=players.get(i);check(p.getInventory().writeNbt(new NbtList()).toString().equals(saved.get(names[i]).getAsString()),"Exact inventory/enchantment/component persistence");check(((SwordEnchantmentState)p).bestiary$harvestReady()==saved.get(names[i]+"Cooldown").getAsLong(),"Player cooldown persistence");}for(var e:read("enchantment-results.json").entrySet())results.put(e.getKey(),e.getValue());results.put("two_client_dedicated_restart_exact_state",true);results.put("complete",true);write("complete.json",results);both("stop");phase=999;}
 }}catch(Throwable error){try{write("server-failure.json",Map.of("phase",phase,"error",error.toString(),"stack",Arrays.toString(error.getStackTrace())));}catch(Exception ignored){}com.witchersbestiary.WitchersBestiary.LOGGER.error("Stage21F native failed",error);phase=999;s.stop(false);}});}
}
